if(el.name==='mode'&&el.closest('#researchForm')){el.closest('.seg').querySelectorAll('.seg-btn').forEach(x=>x.classList.toggle('active',x.contains(el)));}
if(el.id==='feedDays'||el.id==='feedCompany'){feedOpts.days=$('#feedDays').value;feedOpts.company=$('#feedCompany').value;await render();}
if(el.id==='compareDays'){compareDays=el.value;await render();}
