 const total=Object.values(f.counts).reduce((a,b)=>a+b,0);
 const head=`<div class="heading"><div><h1>Daily</h1></div><div class="actions"><button class="btn" data-action="print">Print / PDF</button><button class="btn primary" data-action="refresh" ${!state.companies.length||state.job?.status==='running'?'disabled':''}>↻ Update all companies</button></div></div>`+jobHTML();
 const notes=[f.backfill?.running?dailyNotice('dates',`<span class="spinner">◌</span> Finding dates · ${f.backfill.found}/${f.backfill.checked}`):'',!f.backfill?.running&&f.undated?dailyNotice('undated',`${pl(f.undated,'item has','items have')} no publication date.`):'',state.stats.review?dailyNotice('review',`${pl(state.stats.review,'item','items')} to review. <a href="#archive" data-action="archive-review">Open</a>`):''].join('');
 const filters=`<div class="daily-paper-bar"><div class="filter-row" style="margin:0"><label>Period<select id="feedDays">${[['7','Last 7 days'],['30','Last 30 days'],['90','Last 90 days']].map(([v,l])=>`<option value="${v}" ${feedOpts.days===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Company<select id="feedCompany"><option value="">All companies</option>${state.companies.map(c=>`<option value="${c.id}" ${feedOpts.company===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>${(state.sectors||[]).length?`<label>Sector<select id="feedSector"><option value="">All sectors</option>${state.sectors.map(x=>`<option value="${x.id}" ${feedOpts.sector===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`:''}</div><div class="choices">${chip('type','','All',total)}${chip('type','news','News',f.counts.news)}${chip('type','site','Websites',f.counts.site)}${chip('type','event','Fairs',f.counts.event)}${chip('type','people','People',f.counts.people)}${chip('type','publication','Research',f.counts.publication)}</div></div>`;
 if(!state.companies.length){const g=await gettingStartedBox();if(g)return head+g;}
