 const player=dailyNarration.length?`<section class="daily-player audio-player" aria-label="Daily audio"><div class="audio-intro"><span class="audio-emblem" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 10v4m4-7v10m4-13v16m4-13v10m4-7v4"/></svg></span><div><b>Your Daily, read aloud</b><span>Titles and articles</span></div></div><div class="daily-player-controls"><button class="btn tiny primary audio-start" data-action="narration-start"><span aria-hidden="true">▶</span> Listen to Daily</button>${audioTransport()}</div></section>`:'';
 const paperTones=dailyPaperTones(state.companies);
 const paper=f.items.length?`<section class="daily-paper-list"><div class="daily-paper-list-head"><h2>All news · ${f.items.length}</h2></div>${player}<div class="daily-paper-stories">${f.items.map(i=>dailyNewspaperItem(i,{tone:paperTones.get(i.companyId)??0})).join('')}</div></section>`:empty('Nothing new in this period','Try a longer period or update all companies.');
